import re
from datetime import datetime

_DIGITS = frozenset("0123456789")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"[0-9]{5}-[0-9]{4}")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _all_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = raw.strip()
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    local, at, domain = s.partition("@")
    if at and domain in ("gmail.com", "googlemail.com"):
        local = local.split("+", 1)[0].replace(".", "")
        s = f"{local}@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, _, domain = s.partition("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw.lower()
    cut = len(s)
    for marker in ("x", "ext", "#"):
        pos = s.find(marker)
        if pos != -1:
            cut = min(cut, pos)
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    z = raw.strip()
    if _ZIP_PLUS4_RE.fullmatch(z):
        z = z.split("-", 1)[0]
    if len(z) == 4 and _all_digits(z):
        z = "0" + z
    return z if len(z) == 5 and _all_digits(z) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw) if t.strip()}


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _pick(members, field):
    cands = [m for m in members if m[field]]
    if not cands:
        return ""
    order = sorted(cands, key=lambda m: m["index"])          # input order
    order.sort(key=lambda m: m["updated"], reverse=True)     # newest first (stable)
    order.sort(key=lambda m: m["source"] != "manual")        # manual first (stable)
    return order[0][field]


def _merge(members):
    tags = set()
    for m in members:
        tags |= m["tags"]
    return {
        "first_name": _pick(members, "first_name"),
        "last_name": _pick(members, "last_name"),
        "zip": _pick(members, "zip"),
        "email": _pick(members, "email"),
        "phone": _pick(members, "phone"),
        "source": _pick(members, "source"),
        "tags": ";".join(sorted(tags)),
        "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
        "updated": max(m["updated"] for m in members).strftime("%Y-%m-%d"),
    }


def dedupe_contacts(rows):
    """Normalize, drop unusable rows, and merge duplicate contacts.

    Returns one dict per person, ordered by each person's earliest input row.
    Opted-out people are included with opted_out == "Y"; filter them out
    before sending.
    """
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone", ""))
        if not _is_valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue
        records.append({
            "index": idx,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": row.get("source", "").strip().lower(),
            "tags": _parse_tags(row.get("tags", "")),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
        })

    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    by_email = {}
    by_phone_last = {}
    for pos, rec in enumerate(records):
        if rec["email"]:
            if rec["email"] in by_email:
                union(pos, by_email[rec["email"]])
            else:
                by_email[rec["email"]] = pos
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].lower())
            if key in by_phone_last:
                union(pos, by_phone_last[key])
            else:
                by_phone_last[key] = pos

    # Records are in input order, and groups are inserted in order of their
    # first record, so the output is ordered by each person's earliest row.
    groups = {}
    for pos, rec in enumerate(records):
        groups.setdefault(find(pos), []).append(rec)

    return [_merge(members) for members in groups.values()]
